import {renderReports,refreshScenario} from './reports-ui.mjs';
import {reportCsv,reports} from './reports-data.mjs';
import {sampleRows,actionTemplates,calculate,project,coverage,categories,groups,units,validateRow,exportCsv} from './model.mjs';
import {renderAnalytics} from './analytics.mjs';
import {renderCapstone, readinessBanner, presentationOutline} from './capstone.mjs';
import {tableauCsv} from './capstone-model.mjs';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=Math.abs(v)>0&&Math.abs(v)<1?4:0)=>new Intl.NumberFormat('en-GB',{maximumFractionDigits:d,minimumFractionDigits:d}).format(v);
const state={rows:[],actions:structuredClone(actionTemplates),company:'Unilever Indonesia',year:2025,production:0,productionDemo:false,statuses:{},demo:false,reportYear:2025,reportMetric:'operational',reportFuel:0,reportLeaks:0,view:'overview',filter:0,analytics:{scope:0,group:'',unit:'t'}};
const names={overview:'Ringkasan',analytics:'Tren & komposisi',insights:'Temuan',activities:'Kalkulator tambahan',plan:'Prioritas tindakan',method:'Data & sumber','calculator-plan':'Skenario tambahan'};
const infoIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v2"/></svg>';
const downloadIcon='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/></svg>';
function notice(text){$('#notice').textContent=text;clearTimeout(notice.timer);notice.timer=setTimeout(()=>$('#notice').textContent='',3500);}
function header(title,description,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div><div class="head-actions">${actions}</div></div>`;}
function demoNote(){const illustrative=state.rows.some(r=>r.quality==='illustrative');return `<div class="demo-note">${infoIcon}<span><strong>${state.demo?'Illustrative data, not Unilever’s reported footprint.':illustrative?'Custom scenario · still includes illustrative data.':'User-entered screening estimate.'}</strong> ${state.demo||illustrative?'Sample quantities and factors show how the calculator works. Replace them with verified company data.':'Check factor sources, reporting boundaries and missing categories before using results.'}</span></div>`;}
function overview(){
 const x=calculate(state.rows),p=project(state.rows,state.actions),c=coverage(state.rows,state.statuses),count=c.filter(v=>v.status==='calculated').length;
 const top=Object.entries(x.byGroup).sort((a,b)=>b[1]-a[1]);const largest=top[0];
 return header(esc(state.company),`Manufacturing scenario <span class="slash">·</span> Indonesia <span class="slash">·</span> FY ${state.year}`,`<button class="btn" data-action="export">${downloadIcon} Export data</button><a class="btn primary" href="#activities">Edit activity data <span aria-hidden="true">↗</span></a>`)+demoNote()+readinessBanner(state)+`
 <section class="summary" aria-label="Calculated emissions"><div class="total-panel"><div class="eyebrow">Calculated emissions · partial inventory</div><div class="big-number">${x.calculated?fmt(x.total):'—'}<small>t CO₂e</small></div><p class="muted">${state.year} annual reporting period</p><div class="total-meta"><span class="neutral-chip">${x.calculated} activities calculated</span><span>${x.missing?x.missing+' missing inputs':state.rows.some(r=>r.quality==='illustrative')?'Includes illustrative factors':'User-supplied inputs'}</span></div></div><div class="summary-right"><div class="eyebrow">Your footprint by scope</div><div class="scope-stack" aria-hidden="true">${x.scopes.map((n,i)=>`<span class="s${i+1}" style="width:${x.total?n/x.total*100:0}%"></span>`).join('')}</div><div class="scope-legend">${x.scopes.map((n,i)=>`<div><label><span class="dot s${i+1}"></span>Scope ${i+1}</label><strong>${x.results.some(r=>r.scope===i+1&&r.tonnes!==null)?fmt(n):'—'}</strong><small>${x.results.some(r=>r.scope===i+1&&r.tonnes===null)?'Incomplete data':!x.results.some(r=>r.scope===i+1)?'Not assessed':fmt(x.total?n/x.total*100:0,1)+'% · t CO₂e'}</small></div>`).join('')}</div></div></section>
 <div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2>Where emissions come from</h2><p>Largest sources in the entered inventory</p></div><span class="muted">t CO₂e</span></div><div class="bar-list">${top.length?top.slice(0,5).map(([g,n])=>`<div class="bar-item"><div class="bar-label"><span>${esc(groups[g]??g)}</span><strong>${fmt(n)} <span class="muted">· ${fmt(x.total?n/x.total*100:0,1)}%</span></strong></div><div class="bar-track"><div class="bar-fill" style="width:${largest[1]?n/largest[1]*100:0}%"></div></div></div>`).join(''):'<p class="empty">Add activity data to see your emission sources.</p>'}</div><div class="panel-foot">${largest?`${esc(groups[largest[0]]??largest[0])} account for ${fmt(x.total?largest[1]/x.total*100:0,1)}% of the calculated total.`:'Start with fuel, electricity and purchased materials.'}</div></section>
 <section class="panel opportunity"><div class="eyebrow">Your reduction scenario</div><h2 style="margin-top:10px">Turn the numbers into action.</h2><div class="opportunity-number">${fmt(p.avoided)} <small>t CO₂e</small></div><span class="muted">potential reduction · ${fmt(p.percent,1)}% of subtotal</span><p>${state.actions.filter(a=>a.enabled).length} selected actions. Explore supplier improvements, energy efficiency, and packaging changes. Adjust the assumptions to your business.</p><a href="#plan" class="btn">Explore reduction plan <span aria-hidden="true">→</span></a></section></div>
 <div class="mini-metrics"><section class="panel mini"><span class="eyebrow">Emissions intensity</span><strong>${state.production>0&&x.calculated?fmt(x.total/state.production,3):'—'}</strong><p>t CO₂e per tonne of product · partial inventory</p></section><section class="panel mini"><span class="eyebrow">Scope 3 coverage</span><strong>${count}<span class="muted"> / 15</span></strong><p>Categories with calculated activity rows</p></section><section class="panel mini"><span class="eyebrow">Annual production</span><strong>${fmt(state.production)} <span class="muted">t</span></strong><p>${state.productionDemo?'Illustrative output':'Entered output'} · editable in activity data</p></section></div>`;
}
function activities(){
 const x=calculate(state.rows),list=x.results.filter(r=>!state.filter||r.scope===state.filter);
 return header('Activity data','Enter annual quantities. The dashboard recalculates when you save.',`<button class="btn" data-action="blank">Start blank</button><button class="btn primary" data-action="add">+ Add activity</button>`)+demoNote()+`
 <form id="settings" class="panel settings"><label>Company name<input name="company" readonly value="${esc(state.company)}" maxlength="80" required></label><label>Reporting year<input name="year" type="number" min="2000" max="2100" value="${state.year}" required></label><label>Production (tonnes)<input name="production" type="number" min="0" max="1000000000000" step="any" value="${state.production}" required></label><button class="btn" type="submit">Update</button></form>
 <section class="panel data-panel"><div class="panel-head"><div class="filters" role="group" aria-label="Filter activities by scope">${[0,1,2,3].map(n=>`<button class="filter ${state.filter===n?'selected':''}" data-action="filter" data-scope="${n}" aria-pressed="${state.filter===n}">${n?'Scope '+n:'All activities'}</button>`).join('')}</div><span class="muted">${list.length} activities</span></div><div class="table-wrap"><table><thead><tr><th>Emission source</th><th>Scope</th><th class="num">Activity quantity</th><th class="num">Factor <small>kg CO₂e/unit</small></th><th class="num">t CO₂e</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${list.map(r=>`<tr><td><strong>${esc(r.name)}</strong><small>${r.scope===3?'Cat. '+r.category+' · ':''}${esc(groups[r.group]??r.group)} <span class="row-status">${r.quality==='illustrative'?'Illustrative':'User supplied'}</span></small></td><td><span class="scope-badge"><span class="dot s${r.scope}"></span>${r.scope}</span></td><td class="num">${r.quantity===null?'<span class="unknown">Unknown</span>':fmt(r.quantity,Number.isInteger(r.quantity)?0:2)} <small>${esc(r.unit)}</small></td><td class="num">${r.factor===null?'Unknown':fmt(r.factor,4).replace(/0+$/,'').replace(/\.$/,'')}</td><td class="num"><strong>${r.tonnes===null?'<span class="unknown">Unknown</span>':fmt(r.tonnes,2)}</strong></td><td><button class="btn small" data-action="edit" data-id="${esc(r.id)}" aria-label="Edit ${esc(r.name)}">Edit</button></td></tr>`).join('')}</tbody></table></div>${!list.length?'<div class="empty"><h2>No activities yet</h2><p>Add a source, its quantity, and its emission factor to calculate emissions.</p></div>':''}<div class="table-total"><span>Calculated subtotal · ${state.filter?'Scope '+state.filter:'all scopes'}</span><strong>${fmt(list.reduce((s,r)=>s+(r.tonnes??0),0),2)} t CO₂e</strong></div><p class="panel-foot">Blank values are unknown, not zero. Factors must be in kg CO₂e per activity unit. Emission factors and their sources can be changed in each activity.</p></section>
 <section class="panel coverage-panel"><div class="panel-head"><div><h2>Scope 3 coverage check</h2><p>A calculated category can still contain missing sources. Review all 15 categories.</p></div><span class="chip">Partial inventory</span></div><div class="coverage-grid">${coverage(state.rows,state.statuses).map(c=>`<div class="coverage-item"><span class="category-no">${String(c.id).padStart(2,'0')}</span><div><strong>${esc(c.name)}</strong><small>${c.status==='calculated'?'Activity rows calculated':c.status==='incomplete'?'Inputs missing':c.status==='na'?'Not applicable · '+esc(state.reasons?.[c.id]??'reviewed'):'Not assessed'}</small></div>${['calculated','incomplete'].includes(c.status)?`<span class="status-dot ${c.status==='calculated'?'complete':''}" aria-label="${c.status}"></span>`:`<button class="text-btn" data-action="coverage" data-id="${c.id}">Review</button>`}</div>`).join('')}</div></section>`;
}
function rankedActions(){return state.actions.map(a=>({...a,available:calculate(state.rows.filter(r=>a.groups.includes(r.group))).total,impact:project(state.rows,[{...a,enabled:true}]).avoided})).sort((a,b)=>b.impact-a.impact);}
function plan(){
 const p=project(state.rows,state.actions),actions=rankedActions();
 return header('Reduction plan','Prioritize the biggest sources. Test assumptions before committing investment.',`<button class="btn" data-action="reset-plan">Reset assumptions</button>`)+`<div class="demo-note">${infoIcon}<span><strong>Scenario estimates, not guaranteed savings.</strong> Percentages are adjustable assumptions applied to your current inventory. Costs and payback require a separate business case.</span></div>
 <section class="panel scenario-summary"><div><span class="eyebrow">Current subtotal</span><strong id="plan-base">${fmt(p.baseline)} <small>t CO₂e</small></strong></div><span class="scenario-arrow" aria-hidden="true">→</span><div><span class="eyebrow">With selected actions</span><strong id="plan-projected">${fmt(p.projected)} <small>t CO₂e</small></strong></div><div class="scenario-saving"><span class="eyebrow">Potential reduction</span><strong id="plan-avoided">${fmt(p.avoided)} <small>t CO₂e</small></strong><span id="plan-percent">${fmt(p.percent,1)}% of calculated subtotal</span></div></section>
 <div class="plan-grid"><section><div class="panel-head"><div><h2>Recommended actions</h2><p>Ranked by standalone potential in your inventory</p></div></div><div class="actions-list">${actions.map(a=>`<article class="panel action-card ${a.enabled?'enabled':''}" data-card="${a.id}"><div class="action-top"><label class="action-toggle"><input type="checkbox" data-toggle="${a.id}" ${a.enabled?'checked':''} ${a.available===0?'disabled':''}><span>${esc(a.title)}</span></label><span class="action-impact" id="impact-${a.id}">${fmt(a.impact)} <small>t CO₂e</small></span></div><p>${esc(a.description)}</p><div class="action-tags"><span>${esc(a.owner)}</span><span>${esc(a.effort)}</span><span>${esc(a.horizon)}</span></div><div class="reduction-control"><label for="range-${a.id}">Assumed reduction</label><input id="range-${a.id}" type="range" min="0" max="100" step="1" value="${a.percent}" data-range="${a.id}" ${a.available===0?'disabled':''}><output for="range-${a.id}" id="output-${a.id}">${a.percent}%</output></div><details><summary>Calculation assumption</summary><p>${esc(a.assumption)} ${a.available===0?'No calculated emissions are currently available for this source.':''}</p></details></article>`).join('')}</div></section><aside class="plan-aside"><section class="panel"><h2>From scenario to action</h2><ol class="steps"><li><strong>Confirm the hotspot</strong><p>Replace illustrative inputs with fuel bills, meter readings, procurement volumes, and supplier footprints.</p></li><li><strong>Assign an owner</strong><p>Give each action to the department that can change purchasing or operating decisions.</p></li><li><strong>Build the business case</strong><p>Confirm capital cost, operating savings and implementation constraints before approval.</p></li><li><strong>Measure the result</strong><p>Compare actual emissions and production against the same boundary and reporting period.</p></li></ol></section><section class="panel"><h3>What the model counts</h3><p class="aside-copy">Savings apply only to calculated activities. Missing Scope 3 categories remain outside this scenario. Multiple actions on the same source compound, so avoided emissions are never counted twice.</p><a class="text-btn" href="#method">Read the methodology →</a></section></aside></div>`;
}
function method(){return header('Method & sources','Make the calculation understandable—and the assumptions visible.')+`
 <div class="method-grid"><section class="panel"><h2>One transparent calculation</h2><div class="formula"><span>Activity quantity</span><b>×</b><span>Emission factor</span><b>÷ 1,000</b><strong>tonnes CO₂e</strong></div><p>For every activity, multiply the entered quantity by a factor in <strong>kg CO₂e per matching unit</strong>. Add the results by scope. Convert kilograms to metric tonnes only once.</p><div class="example">Example only: 1,000 litres × 2.68 kg CO₂e/litre ÷ 1,000 = <strong>2.68 t CO₂e</strong>.</div><p>All preloaded quantities and numerical factors are illustrative assumptions. They are <strong>not a sourced factor library</strong> and must be replaced before business reporting. The example fuel factors are simplified and do not establish complete gas coverage.</p></section><section class="panel"><h2>Reporting boundary</h2><ul class="method-list"><li><strong>Scope 1</strong><span>Direct sources under the selected company’s operational control, including fuel, process emissions and refrigerant leaks.</span></li><li><strong>Scope 2</strong><span>Location-based purchased energy. Select the appropriate grid or supplier factor and reporting year. Market-based reporting is not calculated here.</span></li><li><strong>Scope 3</strong><span>Value-chain activities across 15 categories. Categories without data are unassessed, not zero. The displayed total is a partial inventory.</span></li></ul></section>
 <section class="panel"><h2>Using this for Unilever Indonesia</h2><p>This is an independent learning and planning tool using Unilever Indonesia as the business context. Sample activities represent a hypothetical consumer-goods manufacturing operation, not specific Unilever sites.</p><p>Unilever Indonesia’s <a href="https://www.unilever.co.id/files/sustainability-report-2025.pdf#page=184" target="_blank" rel="noopener noreferrer">2025 Sustainability Report, printed page 184</a>, says its Scope 1 and 2 boundary includes manufacturing, warehouse logistics and headquarters. It states that Scope 3 figures were not yet published while data collection and methodology development continued.</p><p>No official Unilever emissions totals are mixed into this scenario. Do not compare the sample location-based Scope 2 estimate directly with a published market-based result.</p></section>
 <section class="panel"><h2>Before using company data</h2><ul class="check-list"><li>Set the company boundary, reporting year and production denominator consistently.</li><li>Use a factor matching the geography, year, technology and activity unit. Record its source, version and gas coverage.</li><li>For refrigerants, use kilograms leaked—not the equipment charge—and a stated GWP assessment version.</li><li>Keep combustion, upstream fuel emissions and transport categories separate to avoid double counting.</li><li>Assess product use and disposal, capital goods, leased assets, and other relevant Scope 3 categories.</li><li>Report biogenic CO₂ separately. Offsets and avoided-emission credits are not subtracted here.</li></ul></section>
 <section class="panel sources"><h2>Reference library</h2><p>These sources explain the accounting and business context; they do not validate the preloaded numerical factors.</p><a href="https://ghgprotocol.org/corporate-standard" target="_blank" rel="noopener noreferrer"><strong>GHG Protocol · Corporate Standard</strong><span>Company boundaries and Scope 1/2 accounting ↗</span></a><a href="https://ghgprotocol.org/scope-2-guidance" target="_blank" rel="noopener noreferrer"><strong>GHG Protocol · Scope 2 Guidance</strong><span>Location-based and market-based reporting ↗</span></a><a href="https://ghgprotocol.org/scope-3-calculation-guidance-2" target="_blank" rel="noopener noreferrer"><strong>GHG Protocol · Scope 3 Calculation Guidance</strong><span>Methods for all 15 value-chain categories ↗</span></a><a href="https://www.unilever.co.id/sustainability/laporan-keberlanjutan/" target="_blank" rel="noopener noreferrer"><strong>Unilever Indonesia · Sustainability reports</strong><span>Published company reporting and disclosure boundaries ↗</span></a><a href="https://gatrik.esdm.go.id/frontend/download_index" target="_blank" rel="noopener noreferrer"><strong>Indonesia ESDM · Electricity reference publications</strong><span>Find and verify the applicable electricity-system factor ↗</span></a></section>
 <section class="panel"><h2>Data handling & limitations</h2><p>Calculations run in your browser. Activity edits stay in this session; refreshing restores the sample. Use Export data to keep a CSV with the activity quantities, factors, sources and coverage notes.</p><p>“User supplied” means you entered the factor; it does not mean independently verified. A complete category requires checking all applicable activities, not merely adding one row.</p><p>Reduction percentages and investment bands are planning assumptions. The dashboard does not estimate financial payback, certify compliance, or provide an assured inventory.</p></section></div>`;}
function render(){
 let view=location.hash.slice(1);state.view=names[view]?view:'overview';
 $('#breadcrumb').textContent=names[state.view];$('.workspace strong').textContent='Unilever Indonesia';
 const supplemental=['activities','calculator-plan'].includes(state.view);
 $('.demo-label').textContent=supplemental?'Skenario internal':'Laporan 2021–2025';
 document.querySelectorAll('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===state.view);if(a.dataset.view===state.view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $('#main').innerHTML=supplemental?'<p class="supplement-note"><strong>Kalkulator tambahan Unilever Indonesia.</strong> Masukkan aktivitas internal dan faktor yang terdokumentasi. Hasil ini terpisah dari angka sustainability report. <a href="#calculator-plan">Uji skenario tambahan →</a> · <button class="text-btn" data-action="export">Ekspor aktivitas</button></p>'+(state.view==='activities'?activities():plan()):renderReports(state,state.view);
}

let exportUrl=null;
function doExport(){const extra=coverage(state.rows,state.statuses).map(c=>`${c.id}. ${c.name}: ${c.status}${state.reasons?.[c.id]?' ('+state.reasons[c.id]+')':''}`).join('; ').replaceAll('"','""');const csv=exportCsv(state.rows,{company:state.company,year:state.year})+'\r\n"Scope 3 coverage","'+extra+'"\r\n"Production tonnes","'+state.production+'"';if(exportUrl)URL.revokeObjectURL(exportUrl);exportUrl=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));$('#editor').innerHTML=`<div class="dialog-head"><div><h2>Export inventory</h2><p class="muted">${state.rows.length} activities · FY ${state.year}</p></div><button class="close-btn" data-action="close" aria-label="Close export">×</button></div><p class="muted">Includes quantities, factors, assumptions, calculated emissions and Scope 3 coverage notes.</p><label>CSV preview<textarea id="csv-preview" rows="9" readonly>${esc(csv)}</textarea></label><div class="dialog-footer"><button class="btn" data-action="copy-csv">Copy CSV</button><a class="btn primary" href="${exportUrl}" download="carbon-ledger-${state.year}.csv">Download CSV</a></div>`;$('#editor').showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='export')doExport();});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});render();

function chartSelection(target){
 if(target.hasAttribute('data-chart-scope')){const value=Number(target.dataset.chartScope);state.analytics.scope=state.analytics.scope===value?0:value;state.analytics.group='';}
 if(target.hasAttribute('data-chart-group')){state.analytics.group=state.analytics.group===target.dataset.chartGroup?'':target.dataset.chartGroup;}
 if(target.hasAttribute('data-chart-reset')){state.analytics.scope=0;state.analytics.group='';}
 if(target.hasAttribute('data-chart-clear-source'))state.analytics.group='';
 render();
}
document.addEventListener('click',e=>{const target=e.target.closest('[data-chart-scope],[data-chart-group],[data-chart-reset],[data-chart-clear-source]');if(target)chartSelection(target);});
document.addEventListener('keydown',e=>{const target=e.target.closest('svg [data-chart-scope],svg [data-chart-group]');if(target&&['Enter',' '].includes(e.key)){e.preventDefault();chartSelection(target);}});
document.addEventListener('change',e=>{if(e.target.id==='chart-unit'){state.analytics.unit=e.target.value;render();}});
function showChartTip(target,x,y){const tip=$('#chart-tooltip');if(!tip)return;tip.textContent=target.dataset.tip;tip.hidden=false;tip.style.left=Math.max(12,Math.min(x+12,innerWidth-tip.offsetWidth-12))+'px';tip.style.top=Math.max(12,Math.min(y+15,innerHeight-tip.offsetHeight-12))+'px';}
document.addEventListener('pointerover',e=>{const t=e.target.closest('[data-tip]');if(t)showChartTip(t,e.clientX,e.clientY);});
document.addEventListener('pointermove',e=>{const t=e.target.closest('[data-tip]');if(t)showChartTip(t,e.clientX,e.clientY);});
document.addEventListener('pointerout',e=>{if(e.target.closest('[data-tip]')&&$('#chart-tooltip'))$('#chart-tooltip').hidden=true;});
document.addEventListener('focusin',e=>{const t=e.target.closest('[data-tip]');if(t){const r=t.getBoundingClientRect();showChartTip(t,r.left,r.top+r.height/2);}});
document.addEventListener('focusout',()=>{if($('#chart-tooltip'))$('#chart-tooltip').hidden=true;});

function numberOrNull(input){const text=input.value.trim();return text===''?null:Number(text);}
function openEditor(id){
 const existing=state.rows.find(r=>r.id===id),r=existing??{id:crypto.randomUUID(),name:'',scope:1,category:0,group:'fuel',quantity:null,unit:'litre',factor:null,factorUnit:'litre',source:'',quality:'user-supplied'};
 const dialog=$('#editor');dialog.innerHTML=`<form id="activity-form" data-id="${esc(r.id)}"><div class="dialog-head"><div><h2>${existing?'Edit':'Add'} activity</h2><p class="muted">Quantity × factor = calculated emissions</p></div><button type="button" class="close-btn" data-action="close" aria-label="Close editor">×</button></div><label>Activity name<input name="name" value="${esc(r.name)}" required maxlength="100" placeholder="e.g. Purchased grid electricity"></label><div class="form-grid"><label>Scope<select name="scope">${[1,2,3].map(s=>`<option value="${s}" ${s===r.scope?'selected':''}>Scope ${s}</option>`).join('')}</select></label><label>Source group<select name="group">${Object.entries(groups).map(([id,name])=>`<option value="${id}" ${id===r.group?'selected':''}>${esc(name)}</option>`).join('')}</select></label></div><label id="category-field" ${r.scope!==3?'hidden':''}>Scope 3 category<select name="category">${categories.map((n,i)=>`<option value="${i+1}" ${i+1===r.category?'selected':''}>${i+1}. ${esc(n)}</option>`).join('')}</select></label><div class="form-grid"><label>Annual quantity<input name="quantity" type="number" min="0" max="1000000000000000" step="any" value="${r.quantity??''}" placeholder="Leave blank if unknown"></label><label>Activity unit<select name="unit">${units.map(u=>`<option ${u===r.unit?'selected':''}>${u}</option>`).join('')}</select></label></div><label>Emission factor <span class="muted">(kg CO₂e per <span id="unit-label">${esc(r.unit)}</span>)</span><input name="factor" type="number" min="0" max="1000000000000000" step="any" value="${r.factor??''}" placeholder="Leave blank if unknown"></label><label>Factor source, year & assumptions<textarea name="source" rows="3" maxlength="600" required placeholder="Publisher, reporting year, geography, factor reference, GWP version if relevant">${esc(r.source)}</textarea></label><label>Factor status<select name="quality"><option value="illustrative" ${r.quality==='illustrative'?'selected':''}>Illustrative assumption</option><option value="user-supplied" ${r.quality!=='illustrative'?'selected':''}>User supplied · not independently verified</option></select></label><p class="field-help">Use a complete CO₂e factor for fuel. For refrigerants, enter leaked kg and the chosen GWP as the factor. Blank quantity or factor stays unknown.</p><div class="form-error" id="form-error" role="alert"></div><div class="dialog-footer">${existing?'<button type="button" class="btn danger" data-action="delete" data-id="'+esc(r.id)+'">Remove activity</button>':'<span></span>'}<button class="btn primary" type="submit">Save activity</button></div></form>`;dialog.showModal();syncScopeFields();
}
function syncScopeFields(){const f=$('#activity-form');if(!f)return;const scope=Number(f.elements.scope.value);$('#category-field').hidden=scope!==3;const allowed=scope===1?['fuel','refrigerant','other']:scope===2?['electricity','other']:['materials','packaging','freight','waste','travel','commuting','other'];for(const o of f.elements.group.options)o.disabled=!allowed.includes(o.value);if(!allowed.includes(f.elements.group.value))f.elements.group.value=allowed[0];}
function updatePlan(){const p=project(state.rows,state.actions);$('#plan-projected').innerHTML=`${fmt(p.projected)} <small>t CO₂e</small>`;$('#plan-avoided').innerHTML=`${fmt(p.avoided)} <small>t CO₂e</small>`;$('#plan-percent').textContent=`${fmt(p.percent,1)}% of calculated subtotal`;for(const a of state.actions){const impact=project(state.rows,[{...a,enabled:true}]).avoided;$('#impact-'+a.id).innerHTML=`${fmt(impact)} <small>t CO₂e</small>`;$('#output-'+a.id).textContent=a.percent+'%';document.querySelector(`[data-card="${a.id}"]`).classList.toggle('enabled',a.enabled);}}
let undoState=null;
function saveUndo(){undoState={rows:structuredClone(state.rows),demo:state.demo,statuses:{...state.statuses},reasons:{...state.reasons}};}
function showUndo(message){clearTimeout(notice.timer);$('#notice').innerHTML=esc(message)+' <button class="undo" data-action="undo">Undo</button>';}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='add')openEditor();if(a==='edit')openEditor(b.dataset.id);if(a==='close')$('#editor').close();
 if(a==='copy-csv'){navigator.clipboard.writeText($('#csv-preview').value).then(()=>{b.textContent='Copied';}).catch(()=>{$('#csv-preview').select();b.textContent='Select & copy';});}
 if(a==='filter'){state.filter=Number(b.dataset.scope);render();}
 if(a==='blank'){saveUndo();if(state.previous)state.previous.comparable=false;state.rows=[];state.demo=false;state.statuses={};state.reasons={};state.filter=0;render();showUndo('Started a blank inventory.');}
 if(a==='delete'){saveUndo();if(state.previous)state.previous.comparable=false;state.rows=state.rows.filter(r=>r.id!==b.dataset.id);state.demo=false;$('#editor').close();render();showUndo('Activity removed.');}
 if(a==='undo'&&undoState){if(state.previous)state.previous.comparable=false;Object.assign(state,undoState);undoState=null;render();notice('Inventory restored.');}
 if(a==='reset-plan'){state.actions=structuredClone(actionTemplates);render();notice('Reduction assumptions reset.');}
 if(a==='coverage'){const id=Number(b.dataset.id);$('#editor').innerHTML=`<form id="coverage-form" data-id="${id}"><div class="dialog-head"><h2>Review category ${id}</h2><button type="button" class="close-btn" data-action="close" aria-label="Close editor">×</button></div><p>${esc(categories[id-1])}</p><label>Status<select name="status"><option value="unassessed">Not assessed</option><option value="na" ${state.statuses[id]==='na'?'selected':''}>Not applicable</option></select></label><label>Reason<textarea name="reason" maxlength="300" rows="3" placeholder="Explain why this category does not apply">${esc(state.reasons?.[id]??'')}</textarea></label><p class="field-help">If the category applies, add its activities instead. Missing data is not a reason to mark a category not applicable.</p><div id="form-error" class="form-error" role="alert"></div><div class="dialog-footer"><span></span><button class="btn primary">Save review</button></div></form>`;$('#editor').showModal();}
});
document.addEventListener('change',e=>{if(e.target.matches('#activity-form [name="scope"]'))syncScopeFields();if(e.target.matches('#activity-form [name="unit"]'))$('#unit-label').textContent=e.target.value;if(e.target.dataset.toggle){const a=state.actions.find(a=>a.id===e.target.dataset.toggle);a.enabled=e.target.checked;updatePlan();}});
document.addEventListener('input',e=>{if(e.target.dataset.range){state.actions.find(a=>a.id===e.target.dataset.range).percent=Number(e.target.value);updatePlan();}});
document.addEventListener('submit',e=>{
 const f=e.target;if(!['settings','activity-form','coverage-form'].includes(f.id))return;e.preventDefault();const data=new FormData(f);
 if(f.id==='settings'){if(state.previous)state.previous.comparable=false;state.company=String(data.get('company')).trim()||'Manufacturing company';state.year=Number(data.get('year'));state.production=Number(data.get('production'));state.productionDemo=false;render();notice('Company settings updated.');}
 if(f.id==='activity-form'){try{const scope=Number(data.get('scope')),r={id:f.dataset.id,name:String(data.get('name')).trim(),scope,category:scope===3?Number(data.get('category')):0,group:String(data.get('group')),quantity:numberOrNull(f.elements.quantity),unit:String(data.get('unit')),factor:numberOrNull(f.elements.factor),factorUnit:String(data.get('unit')),source:String(data.get('source')).trim(),quality:String(data.get('quality'))};if(!r.name||!r.source)throw new Error('Add an activity name and factor source or assumption.');validateRow(r);if(state.previous)state.previous.comparable=false;const i=state.rows.findIndex(v=>v.id===r.id);if(i<0)state.rows.push(r);else state.rows[i]=r;state.demo=false;$('#editor').close();render();notice('Activity saved. Emissions recalculated.');}catch(err){$('#form-error').textContent=err.message;}}
 if(f.id==='coverage-form'){const id=Number(f.dataset.id),status=String(data.get('status')),reason=String(data.get('reason')).trim();if(status==='na'&&!reason){$('#form-error').textContent='Please explain why this category is not applicable.';return;}state.statuses[id]=status;state.reasons??={};state.reasons[id]=reason;$('#editor').close();render();notice('Coverage review updated.');}
});

let supportingExportUrl=null;
function showSupportingExport(kind){
 const isCsv=kind==='tableau-export',content=isCsv?tableauCsv(state.rows,{company:state.company,year:state.year}):presentationOutline(state);
 if(supportingExportUrl)URL.revokeObjectURL(supportingExportUrl);
 supportingExportUrl=URL.createObjectURL(new Blob([isCsv?'\ufeff':'',content],{type:isCsv?'text/csv;charset=utf-8':'text/markdown;charset=utf-8'}));
 $('#editor').innerHTML=`<div class="dialog-head"><h2>${isCsv?'Tableau-ready dataset':'Seven-slide presentation outline'}</h2><button class="close-btn" data-action="close" aria-label="Close export">×</button></div><p class="muted">${isCsv?'One header row and one row per activity. Missing numeric values stay blank; evidence status and calculation status remain explicit. No summary rows are mixed into the dataset.':'Draft speaking content generated from this session. Add team details, verified evidence and dashboard screenshots to your final slides.'}</p><label>Preview<textarea id="csv-preview" rows="12" readonly>${esc(content)}</textarea></label><div class="dialog-footer"><button class="btn" data-action="copy-csv">Copy text</button><a class="btn primary" href="${supportingExportUrl}" download="carbon-ledger-${isCsv?'tableau':'presentation'}-${state.year}.${isCsv?'csv':'md'}">Download ${isCsv?'CSV':'outline'}</a></div>`;
 $('#editor').showModal();
}
function openBaseline(){
 const p=state.previous??{scopes:[null,null,null],source:'',comparable:false};
 $('#editor').innerHTML=`<form id="baseline-form"><div class="dialog-head"><h2>Previous-year baseline</h2><button type="button" class="close-btn" data-action="close" aria-label="Close baseline">×</button></div><p class="muted">Enter FY ${state.year-1} subtotals in t CO₂e. Use the same company boundary, source coverage and Scope 2 location-based method as FY ${state.year}. Do not mix an official whole-company total with this partial sample.</p>${p.year&&p.year!==state.year-1?'<p class="demo-note">The saved baseline belongs to another reporting year. Review all values before saving it for this period.</p>':''}${[1,2,3].map((n,i)=>`<label>Scope ${n} · FY ${state.year-1} · t CO₂e<input name="scope${n}" type="number" min="0" max="1000000000000000" step="any" required value="${p.scopes[i]??''}" placeholder="Enter a documented subtotal"></label>`).join('')}<label>Baseline source & boundary notes<textarea name="source" maxlength="600" rows="3" required>${esc(p.source)}</textarea></label><label class="baseline-check"><input type="checkbox" name="comparable" ${p.comparable&&p.year===state.year-1?'checked':''}><span>I have checked that both years cover the same activities, organizational boundary and accounting method. If unchecked, comparison stays disabled.</span></label><div class="form-error" id="baseline-error" role="alert"></div><div class="dialog-footer"><button class="btn" type="button" data-action="clear-baseline">Clear baseline</button><button class="btn primary" type="submit">Save baseline</button></div></form>`;
 $('#editor').showModal();
}
document.addEventListener('click',e=>{
 const action=e.target.closest('[data-action]')?.dataset.action;
 if(action==='baseline')openBaseline();
 if(action==='clear-baseline'){state.previous=null;$('#editor').close();render();notice('Previous-year baseline cleared.');}
 if(action==='tableau-export'||action==='brief')showSupportingExport(action);
});
document.addEventListener('submit',e=>{
 if(e.target.id!=='baseline-form')return;e.preventDefault();const f=e.target;
 const scopes=[1,2,3].map(n=>numberOrNull(f.elements['scope'+n]));
 if(scopes.some(v=>v===null||!Number.isFinite(v)||v<0||v>1e15)||!f.elements.source.value.trim()){$('#baseline-error').textContent='Enter three non-negative subtotals and a source note.';return;}
 state.previous={year:state.year-1,scopes,source:f.elements.source.value.trim(),comparable:f.elements.comparable.checked};
 $('#editor').close();render();notice('Baseline saved. Review comparability whenever the inventory changes.');
});

const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(context.registerTool({name:'read_carbon_inventory',title:'Read carbon inventory',description:'Read official Unilever Indonesia report data for 2021–2025, including source pages and missing values, plus the separately labelled internal calculator. Does not change data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Expected an empty object.');const x=calculate(state.rows);return {officialReports:reports,selectedReportYear:state.reportYear,internalCalculator:{company:state.company,year:state.year,basis:'Separate user-entered, partial, location-based screening inventory',sampleData:state.demo,illustrativeFactors:state.rows.some(r=>r.quality==='illustrative'),totalTonnes:x.total,scopeTonnes:x.scopes,missingRows:x.missing,coverage:coverage(state.rows,state.statuses),scenario:project(state.rows,state.actions)}};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

let reportExportUrl=null;
document.addEventListener('click',e=>{
 const year=e.target.closest('[data-report-year]');if(year){state.reportYear=Number(year.dataset.reportYear);render();return;}
 const action=e.target.closest('[data-report-action]')?.dataset.reportAction;
 if(action==='reset'){state.reportFuel=0;state.reportLeaks=0;render();}
 if(action==='export'){
  const csv=reportCsv();if(reportExportUrl)URL.revokeObjectURL(reportExportUrl);
  reportExportUrl=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));
  $('#editor').innerHTML=`<div class="dialog-head"><h2>Data laporan 2021–2025</h2><button class="close-btn" data-action="close" aria-label="Tutup ekspor">×</button></div><p class="muted">Satu baris per indikator dan tahun, dengan unit, status, halaman PDF, sumber dan catatan batas. Angka kosong tetap kosong untuk analisis Tableau.</p><label>Pratinjau CSV<textarea id="csv-preview" rows="10" readonly>${esc(csv)}</textarea></label><div class="dialog-footer"><button class="btn" data-action="copy-csv">Salin CSV</button><a class="btn primary" href="${reportExportUrl}" download="unilever-indonesia-emissions-2021-2025.csv">Unduh CSV</a></div>`;
  $('#editor').showModal();
 }
});
document.addEventListener('change',e=>{if(e.target.id==='report-metric'){state.reportMetric=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='report-fuel'||e.target.id==='report-leaks'){state[e.target.id==='report-fuel'?'reportFuel':'reportLeaks']=Number(e.target.value);refreshScenario(state);}});
